/// audio_url   语音              chat.content = 音频 url(duration=秒)
/// file        文件              chat.content = 文件 url(name/size)
/// transfer    转账卡            kind=trans(hi.did.Transaction)
/// trade       交易卡            kind=trade(TradeBase)
/// broadcast   广播
